contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address to) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(to != address(0), "recipient must be non-zero");
        require(address(this).balance >= 0, "balance always non-negative");

        uint256 beforeToBalance = to.balance;
        uint256 beforeCBalance = address(c).balance;

        c.migrateTo(to); if (__ESBMC_reverted()) return;

        assert(to.balance - beforeToBalance == beforeCBalance && address(c).balance == 0);
    }

    receive() external payable {}
}

